/* global self, caches */
// Generated by scripts/build-pwa.mjs. No HTML, API responses or user data are cached.
const VERSION = "__PWA_VERSION__";
const PREFIX = "smartpharm-pwa-";
const SHELL = `${PREFIX}${VERSION}-shell`;
const STATIC = `${PREFIX}${VERSION}-static`;
const MAX_ENTRIES = 100;
const MAX_AGE = 30 * 24 * 60 * 60 * 1000;
const OFFLINE = "/offline.html";
const PUBLIC = [OFFLINE, "/icons/icon-192.png", "/icons/icon-512.png",
  "/icons/maskable-192.png", "/icons/maskable-512.png", "/icons/apple-touch-icon.png", "/icons/favicon.svg"];

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    // Fetch without cookies. A failure leaves the previous worker active.
    for (const path of PUBLIC) {
      const response = await fetch(new Request(path, { credentials: "omit", cache: "reload" }));
      if (!response.ok || response.redirected) throw new Error("Offline assets unavailable");
      await cache.put(path, response);
    }
    // Do not skipWaiting here: an active bill must never be interrupted.
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(PREFIX) && ![SHELL, STATIC].includes(name))
      .map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

// Activation is allowed only from a single sign-in window. Other tabs keep
// their worker until all old clients close; no forced cross-tab reloads.
self.addEventListener("message", event => {
  if (event.data?.type !== "ACTIVATE_UPDATE" || !event.source) return;
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    const source = windows.find(client => client.id === event.source.id);
    // WindowClient.url may retain a document's original URL after an SPA redirect.
    // The signed-out UI supplies the actual current pathname on explicit consent.
    if (windows.length === 1 && source && new URL(source.url).origin === self.location.origin &&
        event.data.pathname === "/login") {
      await self.skipWaiting();
    } else {
      event.source.postMessage({ type: "UPDATE_BLOCKED" });
    }
  })());
});

function publicStatic(url, request) {
  if (url.search || request.cache === "no-store" || request.headers.has("range") || request.headers.has("authorization") || request.headers.has("rsc") ||
      request.headers.has("next-router-prefetch")) return false;
  return (url.pathname.startsWith("/_next/static/") && /\.(?:js|css|woff2?)$/.test(url.pathname)) ||
    ["/fonts/manrope.woff2", "/fonts/jetbrains-mono.woff2"].includes(url.pathname);
}

async function staticResponse(request, event) {
  const cache = await caches.open(STATIC);
  const hit = await cache.match(request);
  if (hit && Date.now() - Number(hit.headers.get("x-smartpharm-cached-at") || 0) < MAX_AGE) return hit;
  if (hit) await cache.delete(request);
  const response = await fetch(new Request(request, { credentials: "omit" }));
  if (response.ok && response.type !== "opaque" && !response.redirected &&
      !/private|no-store/i.test(response.headers.get("cache-control") || "") &&
      !response.headers.has("set-cookie") &&
      !/cookie|authorization|\*/i.test(response.headers.get("vary") || "")) {
    const copy = response.clone();
    event.waitUntil((async () => {
      try {
        const headers = new Headers(copy.headers);
        headers.set("x-smartpharm-cached-at", String(Date.now()));
        headers.delete("content-encoding"); headers.delete("content-length");
        await cache.put(request, new Response(await copy.arrayBuffer(), { status: copy.status, headers }));
        const keys = await cache.keys();
        await Promise.all(keys.slice(0, Math.max(0, keys.length-MAX_ENTRIES)).map(key => cache.delete(key)));
      } catch { /* Storage limits never fail a successful network response. */ }
    })());
  }
  return response;
}

self.addEventListener("fetch", event => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin ||
      /^\/api(?:\/|$)/.test(url.pathname) || request.headers.has("authorization")) return;
  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        // Keep deep links, redirects, server errors and HTTP auth semantics intact.
        // No navigation response enters Cache Storage.
        return await fetch(request);
      } catch {
        const cache = await caches.open(SHELL);
        return (await cache.match(OFFLINE)) || Response.error();
      }
    })());
  } else if (PUBLIC.includes(url.pathname) && !url.search) {
    event.respondWith((async () => (await (await caches.open(SHELL)).match(url.pathname)) || fetch(request))());
  } else if (publicStatic(url, request)) {
    event.respondWith(staticResponse(request, event));
  }
});
